import { ApiPropertyOptional } from '@nestjs/swagger';
import { IsDateString, IsOptional } from 'class-validator';

// -----------------------------------------------------------------------------
// sisiMove — Complete Journey DTO
// -----------------------------------------------------------------------------
//
// HTTP request body for completing a Journey.
//
// The following values are intentionally NOT part of this DTO:
// - journeyPublicId → supplied by the route parameter
// - correlationId   → generated by the controller
// - causationId     → application-layer concern
//
// The controller/application layer constructs the CompleteJourneyCommand
// from the validated HTTP input.
//
// -----------------------------------------------------------------------------

export class CompleteJourneyDto {
  // ---------------------------------------------------------------------------
  // Completion Timestamp
  // ---------------------------------------------------------------------------

  @ApiPropertyOptional({
    example: '2026-08-15T15:30:00.000Z',
    description:
      'Optional effective journey completion timestamp. When omitted, the backend uses the current time.',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  readonly completedAt?: string;
}
